nking link_id (invoice id), ejv_header_id, disbursement_status_code UPLOADED, sequence, link_type INVOICE; added to session."},{"name":"EJVLinkType.INVOICE.value","direction":"reads","what":"Link type constant for invoice-ejv associations."},{"name":"InvoiceStatus.REFUNDED.value, InvoiceStatus.REFUND_REQUESTED.value, InvoiceStatus.CREDITED.value","direction":"reads","what":"Status constants checked to determine if invoice is a reversal."},{"name":"current_app.config.get('CGI_BCREG_CLIENT_CODE')","direction":"reads","what":"Config key (value '112') used to filter distribution codes by batch type rule."},{"name":"db.session.add, db.session.flush, db.session.commit, db.session.rollback","direction":"sends","what":"Session operations to persist EjvFileModel, EjvHeaderModel, EjvLinkModel, invoice status updates."},{"name":"create_inbox_and_trg_files","direction":"sends","what":"Creates inbox and .trg files from ejv_content string, returns file_path_with_name and trg_file_path."},{"name":"upload","direction":"sends","what":"Uploads ejv_content, filename, file_path_with_name, and trg_file_path to FTP."},{"name":"get_file_name, get_batch_number, get_batch_header, get_invoices_for_disbursement, get_invoices_for_refund_reversal, get_effective_date, get_journal_name, get_journal_batch_name, get_distribution_string, get_jv_header, get_jv_line, get_batch_trailer","direction":"sends","what":"Classmethod helpers generating filenames, batch data, JV headers, JV lines, and trailers."},{"name":"_find_line_items_by_invoice_and_distribution, _get_partners_by_batch_type","direction":"sends","what":"Classmethod helpers returning PaymentLineItemModel list and CorpTypeModel list respectively."}]}

